259	    @Override
260	    @Transactional
261	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
262	        rejectWhenDailyLimitReached(owner);
263	        rejectWhenCityAtCapacity(owner);
264	        List<Owner> householdMembers = assignHousehold(owner, sharesHousehold);
265	        rejectWhenDuplicateIdentity(owner);
266	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
267	        if (owner.getCustomerCode() == null) {
268	            owner.setCustomerCode(deriveCustomerCode(owner));
269	        }
270	        if (owner.getNamesakeCount() == null) {
271	            owner.setNamesakeCount(countNamesakes(owner));
272	        }
273	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
274	        ownerRepository.save(owner);
275	    }
276	
277	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
278	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
279	
280	    /**
281	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
282	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
283	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
284	     * today by the controller, determines which day is counted — the same accumulation path as the
285	     * daily-limit rule.
286	     */
287	    private boolean exceedsBulkSignupThreshold(Owner owner) {
288	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
289	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
290	    }
291	
292	    /**
293	     * Count the existing owners that already share this owner's first name and last name,
294	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
295	     * before the owner is persisted, so it reflects the owners present at creation time.
296	     */
297	    private int countNamesakes(Owner owner) {
298	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
299	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
300	        return (int) ownerRepository.findAll().stream()
301	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
302	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
303	            .count();
304	    }
305	
306	    /**
307	     * Reconcile the owner's household and return its existing members. Owners are in the same
308	     * household when their last name and address match (compared case-insensitively with collapsed
309	     * whitespace). When another owner already lives there and {@code sharesHousehold} is set, the
310	     * new owner and every existing member are given the same stable shared {@code householdId} so
311	     * they form one household; without the opt-in the owner is treated as living alone (no shared
312	     * identifier). Duplicate detection no longer happens here: it is consolidated into the derived
313	     * {@code identityKey} (see {@link #rejectWhenDuplicateIdentity(Owner)}). The returned list is the
314	     * existing members that make up this owner's household (empty when the owner lives alone), so
315	     * callers can derive the household size after this create.
316	     */
317	    private List<Owner> assignHousehold(Owner owner, boolean sharesHousehold) {
318	        if (!sharesHousehold) {
319	            return List.of();
320	        }
321	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
322	        String address = AddressNormalizer.canonical(owner.getAddress());
323	        List<Owner> householdMembers = ownerRepository.findAll().stream()
324	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
325	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
326	            .toList();
327	        if (householdMembers.isEmpty()) {
328	            return householdMembers;
329	        }
330	        String householdId = householdMembers.stream()
331	            .map(Owner::getHouseholdId)
332	            .filter(Objects::nonNull)
333	            .findFirst()
334	            .orElseGet(() -> deriveHouseholdId(lastName, address));
335	        owner.setHouseholdId(householdId);
336	        for (Owner member : householdMembers) {
337	            if (!householdId.equals(member.getHouseholdId())) {
338	                member.setHouseholdId(householdId);
339	                ownerRepository.save(member);
340	            }
341	        }
342	        return householdMembers;
343	    }
344	
345	    /**
346	     * Derive a stable, shared household identifier from the normalized last name and address, so
347	     * every owner in the same household deterministically maps to the same value.
348	     */
349	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
350	        String key = normalizedLastName + "\n" + normalizedAddress;
351	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
352	    }
353	
354	    /**
355	     * Reject the create when the owner's derived {@code identityKey} exactly matches that of an
356	     * existing owner. The key —
357	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the single value
358	     * into which the former separate telephone, e-mail and household duplicate checks are
359	     * consolidated: only an exact whole-key match is a duplicate, so two members of the same
360	     * household with different telephones (hence different keys) are both allowed. Evaluated after
361	     * the household has been reconciled (so the {@code householdId} segment is settled) and before
362	     * the owner is persisted, so it reflects the owners present at creation time.
363	     */
364	    private void rejectWhenDuplicateIdentity(Owner owner) {
365	        String identityKey = IdentityKeyNormalizer.derive(owner);
366	        boolean duplicate = ownerRepository.findAll().stream()
367	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
368	        if (duplicate) {
369	            throw new DuplicateIdentityException(
370	                "an owner with identity key " + identityKey + " already exists");
371	        }
372	    }
373	
374	    /** Maximum number of owners that may be created on any single day (by registration date). */
375	    private static final long DAILY_OWNER_LIMIT = 100L;
376	
377	    /**
378	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
379	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
380	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
381	     * to today by the controller, determines which day the limit is checked against.
382	     */
383	    private void rejectWhenDailyLimitReached(Owner owner) {
384	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
385	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
386	            throw new DailyOwnerLimitExceededException(
387	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
388	        }
389	    }
390	
391	    /**
392	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
393	     * before the owner is persisted, so it reflects the owners present at creation time.
394	     */
395	    private long countOwnersRegisteredOn(LocalDate day) {
396	        return ownerRepository.findAll().stream()
397	            .filter(existing -> day.equals(existing.getRegistrationDate()))
398	            .count();
399	    }
400	
401	    /** Maximum number of owners allowed to live in any single city. */
402	    private static final long CITY_CAPACITY = 50L;
403	
404	    /**
405	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
406	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
407	     * is persisted, so it reflects the owners present at creation time.
408	     */
409	    private void rejectWhenCityAtCapacity(Owner owner) {
410	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
411	            throw new CityCapacityExceededException(
412	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
413	        }
414	    }
415	
416	    /**
417	     * Count the existing owners that already live in this owner's city, compared
418	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
419	     * owner is persisted, so it reflects the owners present at creation time.
420	     */
421	    private long countOwnersInCity(Owner owner) {
422	        String city = IdentityNormalizer.normalize(owner.getCity());
423	        return ownerRepository.findAll().stream()
424	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
425	            .count();
426	    }
427	
428	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
429	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
430	        "NSW", new int[] {2000, 2099},
431	        "VIC", new int[] {3000, 3099},
432	        "QLD", new int[] {4000, 4099});
433	
434	    /** Region code used when the postcode maps to no known region (or is absent). */
435	    private static final String UNKNOWN_REGION = "UNKNOWN";
436	
437	    /**
438	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
439	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
440	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
441	     * name. No sequence number is used; the identity is fully derived from the region and hash.
442	     */
443	    private String deriveCustomerCode(Owner owner) {
444	        String region = regionForPostcode(owner.getPostcode());
445	        String telephone = TelephoneNormalizer.toE164(owner.getTelephone());
446	        if (telephone == null) {
447	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
448	        }
449	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
450	        return region + "-" + sha256Hex8(telephone + lastName);
451	    }
452	
453	    /**
454	     * Returns the region code whose inclusive postcode range contains {@code postcode}
455	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
456	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
457	     */
458	    private static String regionForPostcode(String postcode) {
459	        if (postcode == null || !postcode.matches("\\d{4}")) {
460	            return UNKNOWN_REGION;
461	        }
462	        int value = Integer.parseInt(postcode);
463	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
464	            int[] range = entry.getValue();
465	            if (value >= range[0] && value <= range[1]) {
466	                return entry.getKey();
467	            }
468	        }
469	        return UNKNOWN_REGION;
470	    }
471	
472	    /**
473	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
474	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
475	     */
476	    private static String sha256Hex8(String value) {
477	        try {
478	            byte[] digest = MessageDigest.getInstance("SHA-256")
479	                .digest(value.getBytes(StandardCharsets.UTF_8));
480	            StringBuilder sb = new StringBuilder(8);
481	            for (int i = 0; i < 4; i++) {
482	                sb.append(String.format("%02X", digest[i]));
483	            }
484	            return sb.toString();
485	        }
486	        catch (NoSuchAlgorithmException e) {
487	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
488	        }
489	    }
